#!/usr/bin/env python3
"""Bootstrap IPOFins Cursor customization. Writes all files from embedded manifest."""
from __future__ import annotations

import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

FILES: dict[str, str] = json.loads('{".cursor/rules/ipofins-core.mdc": "---\\ndescription: IPOFins core project rules\\nalwaysApply: true\\n---\\n\\n# IPOFins.com — core rules\\n\\n## Stack\\n\\n- Astro 4.x, TypeScript strict, PostgreSQL 16 (Neon), Node.js 22, Tailwind CSS v4\\n- Schema: `db/migrations/`, `db/verify-schema.mjs`\\n- Read `DESIGN.md` and `CONTEXT.md` before UI / pipeline work\\n\\n## Git\\n\\n- **Never merge to `main` from agents** — feature branch only\\n\\n## Absolute rules\\n\\n- Money: `NUMERIC`; timestamps: `TIMESTAMPTZ`; rupee ₹\\n- Smart money: `mv_smart_money_latest` (not raw `fund_holdings` aggregates)\\n- Use `stock_id`, not `security_id`\\n", ".cursor/rules/git-workflow.mdc": "---\\ndescription: Git workflow — never merge main from agents\\nalwaysApply: true\\n---\\n\\n- Never merge to `main` from agent sessions\\n- `git push origin HEAD` on the active feature branch\\n- Deploy via GitHub Actions **Build & Deploy** on that branch\\n", ".cursor/rules/db-layer.mdc": "---\\ndescription: Database and pipeline layer\\nglobs: db/**,scripts/pipeline/**\\nalwaysApply: false\\n---\\n\\n- No `SELECT *`; explicit columns only\\n- `TIMESTAMPTZ` not bare `TIMESTAMP`\\n- `NUMERIC` for money; `stock_id` FK to `stocks(id)`\\n- Migrations under `db/migrations/`\\n", ".cursor/rules/astro-pages.mdc": "---\\ndescription: Astro pages and components\\nglobs: src/pages/**,src/components/**\\nalwaysApply: false\\n---\\n\\n- Default `prerender = true`\\n- SEO titles/descriptions; canonical URLs\\n- `font-mono` for numbers; Indian date formatting\\n", ".cursor/rules/design-system.mdc": "---\\ndescription: Design system — read DESIGN.md\\nglobs: src/**/*.astro,src/**/*.tsx,src/**/*.css,src/**/*.html\\nalwaysApply: false\\n---\\n\\nRead `DESIGN.md` before UI changes. Use theme tokens from `src/styles/global.css`, 8px spacing, `dark:` variants.\\n", ".cursor/rules/accessibility.mdc": "---\\ndescription: WCAG AA accessibility\\nglobs: src/**/*.astro,src/**/*.tsx\\nalwaysApply: false\\n---\\n\\nWCAG AA: contrast, focus states, labels, table headers, reduced motion.\\n", ".cursor/rules/typography.mdc": "---\\ndescription: Typography — font-mono for numbers\\nglobs: src/**/*.astro,src/**/*.tsx,src/**/*.css\\nalwaysApply: false\\n---\\n\\n- `font-sans` for prose; `font-mono` for all numeric values\\n- Rupee ₹; `Intl.NumberFormat(\'en-IN\')`\\n", ".cursor/skills/scaffold-postgres-migration/SKILL.md": "---\\nname: scaffold-postgres-migration\\ndescription: Scaffold a new PostgreSQL migration in db/migrations with IPOFins conventions (TIMESTAMPTZ, NUMERIC, stock_id).\\n---\\n\\n# Scaffold Postgres migration\\n\\n1. Name: `db/migrations/NNN_short_snake_case.sql` (next sequence number).\\n2. Use `TIMESTAMPTZ` for all timestamps; `NUMERIC` for money.\\n3. Reference `stocks(id)` as `stock_id` — never `security_id`.\\n4. Avoid `SELECT *` in views; name columns explicitly.\\n5. Add indexes for FKs and filter columns used in pipelines.\\n6. After authoring: `node scripts/validate-migration.mjs db/migrations/NNN_....sql`\\n7. Apply (staging only): `node scripts/node-with-ca.mjs scripts/apply-migration.mjs db/migrations/NNN_....sql`\\n8. Run `node db/verify-schema.mjs`.\\n", ".cursor/skills/build-astro-ipo-page/SKILL.md": "---\\nname: build-astro-ipo-page\\ndescription: Build or extend an Astro IPO detail page with SEO, JSON-LD, and DESIGN.md tokens.\\n---\\n\\n# Build Astro IPO page\\n\\n1. Read `DESIGN.md` and reuse `IPOCard` / existing IPO components.\\n2. Page under `src/pages/` with `export const prerender = true`.\\n3. Title ≤60 chars; meta description ≤160; canonical URL.\\n4. Financial numbers: `font-mono`, `Intl.NumberFormat(\'en-IN\')`, rupee U+20B9.\\n5. Add `FinancialProduct` JSON-LD when appropriate.\\n6. Run `npm run check` before finishing.\\n", ".cursor/skills/debug-pipeline-failure/SKILL.md": "---\\nname: debug-pipeline-failure\\ndescription: Systematically debug scripts/pipeline failures (ingestion_runs, logs, staging DB).\\ndisable-model-invocation: true\\n---\\n\\n# Debug pipeline failure\\n\\n1. Identify script from `package.json` (`pipeline:*`, `db:*`).\\n2. Check `ingestion_runs` / `data_quality_issues` in Neon staging.\\n3. Re-run with `node scripts/node-with-ca.mjs <script>` and capture stderr.\\n4. Never run destructive pipelines against prod (`.env.prod-backup`).\\n5. For SI: `npm run validate:si-pipeline` and `npm run validate:si-data`.\\n6. Invoke subagent `pipeline-debugger` for deep dives.\\n", ".cursor/skills/dark-mode-audit/SKILL.md": "---\\nname: dark-mode-audit\\ndescription: Audit Astro/TSX UI for dark mode token usage and contrast.\\n---\\n\\n# Dark mode audit\\n\\n1. Read `DESIGN.md` and `src/styles/global.css`.\\n2. Find hardcoded `#fff` / `#000` / raw hex — replace with `surface-*` / `dark:` tokens.\\n3. Verify contrast in light and dark at 375px width.\\n4. Tables: sticky first column on mobile.\\n", ".cursor/skills/build-ipo-card/SKILL.md": "---\\nname: build-ipo-card\\ndescription: Implement or adjust IPO card UI per DESIGN.md (GMP, subscription, staleness).\\n---\\n\\n# Build IPO card\\n\\n1. Extend `IPOCard` or sibling in `src/components/` — no one-off colours.\\n2. Show GMP median/range, subscription multiple, source count when available.\\n3. Numeric fields: `font-mono`; status via `RiskBadge`.\\n4. Loading: `.skeleton` not spinners for primary content.\\n", ".cursor/skills/accessibility-audit/SKILL.md": "---\\nname: accessibility-audit\\ndescription: WCAG AA audit for Astro/TSX pages (contrast, labels, tables).\\n---\\n\\n# Accessibility audit\\n\\n1. Apply rule `accessibility.mdc`.\\n2. Check focus rings, `aria-label` on icon buttons, table `scope`.\\n3. Run keyboard-only pass on primary flows.\\n4. Document fixes as minimal diffs.\\n", ".cursor/skills/figma-to-astro/SKILL.md": "---\\nname: figma-to-astro\\ndescription: Translate Figma frames to Astro components using DESIGN.md tokens (Figma MCP).\\n---\\n\\n# Figma to Astro\\n\\n1. Read `DESIGN.md`; map colours to Tailwind theme tokens only.\\n2. Use Figma MCP (see `.cursor/mcp.json.example`) for specs.\\n3. Output Astro + Tailwind v4; `font-mono` for numbers.\\n4. Prefer existing components before new primitives.\\n", ".cursor/subagents/db-schema-guardian.md": "---\\nname: db-schema-guardian\\ndescription: Review migrations and queries for IPOFins schema rules (TIMESTAMPTZ, NUMERIC, stock_id, no SELECT *).\\n---\\n\\nYou guard the Neon schema. Reject `TIMESTAMP` without time zone, `FLOAT` money, `security_id`, and `SELECT *`. Ensure migrations live in `db/migrations/` and match `db/verify-schema.mjs`.\\n", ".cursor/subagents/pipeline-debugger.md": "---\\nname: pipeline-debugger\\ndescription: Diagnose failures in scripts/pipeline and db compute scripts using ingestion logs.\\n---\\n\\nTrace pipeline failures end-to-end. Use staging `DATABASE_URL` only unless user confirms prod. Suggest minimal fixes and validation commands (`validate:si-pipeline`, `validate:si-data`).\\n", ".cursor/subagents/seo-auditor.md": "---\\nname: seo-auditor\\ndescription: Audit Astro routes for titles, meta, canonicals, structured data, and internal links.\\n---\\n\\nCheck `src/pages/` for SEO limits, JSON-LD on IPO pages, sitemap coverage, and E-E-A-T fields where required.\\n", ".cursor/subagents/astro-builder.md": "---\\nname: astro-builder\\ndescription: Implement Astro pages/components following DESIGN.md and astro-pages rules.\\n---\\n\\nBuild static Astro pages with prerender, Indian number formatting, and component reuse. Run `npm run check` when touching types.\\n", ".cursor/commands/refresh-mvs.md": "# Refresh materialized views\\n\\nRun on **staging** unless the user explicitly requests prod.\\n\\n```bash\\nnpm run db:refresh-si-views\\n```\\n\\nAlso refresh smart-money MVs (includes `mv_smart_money_latest`) via SQL on staging:\\n\\n```bash\\nnode scripts/node-with-ca.mjs -e \\"import { sql } from \'./scripts/lib/db.mjs\'; await sql`SELECT refresh_all_views()`; console.log(\'refresh_all_views done\');\\"\\n```\\n\\nIf the one-liner fails, run `SELECT refresh_all_views();` in the Neon SQL editor after monthly MF load.\\n", ".cursor/commands/deploy-branch.md": "# Deploy current branch (no merge to main)\\n\\n1. Commit and `git push origin HEAD` on the feature branch.\\n2. GitHub Actions → **Build & Deploy** → run workflow on **this branch** (not `main`).\\n3. Use force export / predeploy flags only when the user requests.\\n4. **Never merge to `main` from agent sessions.**\\n", ".cursor/commands/pr.md": "# Commit, push, PR prep (no merge to main)\\n\\n1. `git status` / `git diff` — stage relevant files only.\\n2. Commit on the **current feature branch** with a clear message.\\n3. `git push origin HEAD`\\n4. Open a PR only if the user explicitly asked; default target is **not** auto-merge to `main`.\\n", ".cursor/commands/compute-si.md": "# Super-investor compute chain\\n\\nStaging unless user confirms prod:\\n\\n```bash\\nnpm run db:fix-shp-pct-100\\nnpm run db:compute-si:all\\nnpm run validate:si-data\\n```\\n\\nOptional refresh after compute:\\n\\n```bash\\nnpm run db:refresh-si-views\\n```\\n", ".cursor/commands/add-ipo.md": "# Add a new IPO\\n\\n1. Sync broker data: `npm run pipeline:ipo` (staging).\\n2. Verify IPO appears in DB / export JSON paths under `public/data/`.\\n3. Add or extend Astro route under `src/pages/` (reuse IPO components).\\n4. SEO + JSON-LD; run `npm run check` and site build if user requests.\\n", ".cursor/hooks.json": "{\\n  \\"version\\": 1,\\n  \\"hooks\\": {\\n    \\"afterFileEdit\\": [\\n      {\\n        \\"command\\": \\"node .cursor/hooks/validate-sql.mjs\\"\\n      }\\n    ],\\n    \\"stop\\": [\\n      {\\n        \\"command\\": \\"node .cursor/hooks/suggest-check.mjs\\"\\n      }\\n    ]\\n  }\\n}\\n", ".cursor/hooks/validate-sql.mjs": "#!/usr/bin/env node\\n/**\\n * afterFileEdit hook: flag risky SQL in db/migrations/*.sql\\n * - TIMESTAMP without TIMESTAMPTZ\\n * - SELECT *\\n */\\nimport { readFileSync } from \'fs\';\\n\\nlet input = \'\';\\ntry {\\n  for await (const chunk of process.stdin) input += chunk;\\n} catch {\\n  input = \'\';\\n}\\n\\nlet payload = {};\\ntry {\\n  payload = input ? JSON.parse(input) : {};\\n} catch {\\n  payload = {};\\n}\\n\\nconst filePath = payload.filePath || payload.path || payload.file || \'\';\\nconst normalized = String(filePath).replace(/\\\\\\\\/g, \'/\');\\nif (!normalized.includes(\'db/migrations/\') || !normalized.endsWith(\'.sql\')) {\\n  process.stdout.write(JSON.stringify({}));\\n  process.exit(0);\\n}\\n\\nlet sql = \'\';\\ntry {\\n  sql = readFileSync(filePath, \'utf8\');\\n} catch {\\n  process.stdout.write(JSON.stringify({}));\\n  process.exit(0);\\n}\\n\\nconst issues = [];\\nif (/\\\\bSELECT\\\\s+\\\\*/i.test(sql)) {\\n  issues.push(\'Avoid SELECT * — name columns explicitly.\');\\n}\\nif (/\\\\bTIMESTAMP\\\\b(?!TZ)/i.test(sql) && /\\\\bTIMESTAMPTZ\\\\b/i.test(sql) === false) {\\n  if (/\\\\bTIMESTAMP\\\\s+WITHOUT\\\\s+TIME\\\\s+ZONE\\\\b/i.test(sql) || /\\\\bTIMESTAMP\\\\b(?!TZ)/i.test(sql)) {\\n    issues.push(\'Use TIMESTAMPTZ instead of TIMESTAMP without time zone.\');\\n  }\\n}\\n// simpler TIMESTAMP check\\nif (/\\\\bTIMESTAMP(?!TZ)\\\\b/i.test(sql)) {\\n  issues.push(\'Use TIMESTAMPTZ instead of bare TIMESTAMP.\');\\n}\\n\\nif (!issues.length) {\\n  process.stdout.write(JSON.stringify({}));\\n  process.exit(0);\\n}\\n\\nprocess.stdout.write(JSON.stringify({\\n  userMessage: issues.join(\' \'),\\n}));\\n", ".cursor/hooks/suggest-check.mjs": "#!/usr/bin/env node\\n/** stop hook: suggest npm run check after src/ or db/ edits in session */\\nlet input = \'\';\\ntry {\\n  for await (const chunk of process.stdin) input += chunk;\\n} catch {\\n  input = \'\';\\n}\\n\\nlet payload = {};\\ntry {\\n  payload = input ? JSON.parse(input) : {};\\n} catch {\\n  payload = {};\\n}\\n\\nconst touched = JSON.stringify(payload);\\nconst interesting = /src\\\\/(pages|components|lib)\\\\//.test(touched) || /db\\\\//.test(touched) || /\\\\.astro/.test(touched) || /\\\\.tsx/.test(touched);\\nif (!interesting) {\\n  process.stdout.write(JSON.stringify({}));\\n  process.exit(0);\\n}\\n\\nprocess.stdout.write(JSON.stringify({\\n  followupMessage: \'If you changed Astro/TS or DB types, run `npm run check` before committing.\',\\n}));\\n", ".cursor/mcp.json.example": "{\\n  \\"mcpServers\\": {\\n    \\"figma\\": {\\n      \\"url\\": \\"https://mcp.figma.com/mcp\\"\\n    },\\n    \\"puppeteer\\": {\\n      \\"command\\": \\"npx\\",\\n      \\"args\\": [\\n        \\"-y\\",\\n        \\"@modelcontextprotocol/server-puppeteer\\"\\n      ]\\n    },\\n    \\"brave-search\\": {\\n      \\"command\\": \\"npx\\",\\n      \\"args\\": [\\n        \\"-y\\",\\n        \\"@modelcontextprotocol/server-brave-search\\"\\n      ],\\n      \\"env\\": {\\n        \\"BRAVE_API_KEY\\": \\"YOUR_BRAVE_API_KEY\\"\\n      }\\n    },\\n    \\"github\\": {\\n      \\"command\\": \\"npx\\",\\n      \\"args\\": [\\n        \\"-y\\",\\n        \\"@modelcontextprotocol/server-github\\"\\n      ],\\n      \\"env\\": {\\n        \\"GITHUB_PERSONAL_ACCESS_TOKEN\\": \\"YOUR_GITHUB_PAT\\"\\n      }\\n    },\\n    \\"refero\\": {\\n      \\"command\\": \\"npx\\",\\n      \\"args\\": [\\n        \\"-y\\",\\n        \\"refero-mcp-server\\"\\n      ]\\n    }\\n  }\\n}\\n", ".cursor/automations/drafts.md": "# Cursor automation drafts (create via /automate in Agents Window)\\n\\n## 1. Nightly SI validation (staging)\\n\\n- **Trigger:** Schedule (weeknights IST)\\n- **Action:** Run `npm run validate:si-data` on staging; open GitHub issue if failures.\\n\\n## 2. Post-merge export reminder\\n\\n- **Trigger:** Git push to `feature/*`\\n- **Action:** Comment on PR reminding to run `npm run db:refresh-si-views` after SHP pipeline changes.\\n\\n## 3. Pipeline failure triage\\n\\n- **Trigger:** Manual or CI failure webhook\\n- **Action:** Invoke `pipeline-debugger` subagent with last `ingestion_runs` error payload.\\n", ".cursor/README.md": "# Cursor customization — IPOFins\\n\\n| Layer | Path |\\n|-------|------|\\n| Rules | `.cursor/rules/*.mdc` |\\n| Skills | `.cursor/skills/*/SKILL.md` |\\n| Subagents | `.cursor/subagents/*.md` |\\n| Commands | `.cursor/commands/*.md` → `/command-name` |\\n| MCP | Copy `.cursor/mcp.json.example` → `.cursor/mcp.json` (gitignored) |\\n| Hooks | `.cursor/hooks.json` + `.cursor/hooks/*` |\\n| Automations | `.cursor/automations/drafts.md` |\\n\\n## Setup\\n\\n1. `python scripts/bootstrap_cursor_config.py` — regenerate team config (UTF-8).\\n2. Copy MCP example and add API keys.\\n3. Session start: `@CONTEXT.md` `@DESIGN.md` then your task.\\n\\n## Git\\n\\n- `.cursor/mcp.json` is gitignored; rules/skills/hooks are committed.\\n", "scripts/validate-migration.mjs": "#!/usr/bin/env node\\n/**\\n * CLI SQL migration checks (no DB connection).\\n * Usage: node scripts/validate-migration.mjs db/migrations/NNN_name.sql\\n */\\nimport { readFileSync } from \'fs\';\\nimport { resolve } from \'path\';\\n\\nconst file = resolve(process.cwd(), process.argv[2] || \'\');\\nif (!file || !file.endsWith(\'.sql\')) {\\n  console.error(\'Usage: node scripts/validate-migration.mjs db/migrations/NNN_name.sql\');\\n  process.exit(1);\\n}\\n\\nconst sql = readFileSync(file, \'utf8\');\\nlet failed = false;\\n\\nif (/\\\\bSELECT\\\\s+\\\\*/i.test(sql)) {\\n  console.error(\'FAIL: SELECT * found — list columns explicitly.\');\\n  failed = true;\\n}\\nif (/\\\\bTIMESTAMP(?!TZ)\\\\b/i.test(sql)) {\\n  console.error(\'FAIL: use TIMESTAMPTZ instead of TIMESTAMP.\');\\n  failed = true;\\n}\\nif (/\\\\bsecurity_id\\\\b/i.test(sql)) {\\n  console.warn(\'WARN: prefer stock_id (stocks.id) over security_id.\');\\n}\\n\\nif (failed) process.exit(1);\\nconsole.log(\'OK:\', process.argv[2]);\\n", "CONTEXT.md": "# IPOFins / Finverse - project context\\n\\nUpdate weekly. Include @CONTEXT.md at session start.\\n\\n## Workflow\\n\\n- **Never merge to `main` from agents** — feature branches only.\\n- Deploy: GitHub Actions **Build & Deploy** from the feature branch.\\n\\n## Stack\\n\\n- Astro 4.x, TypeScript, Tailwind v4, Neon PostgreSQL 16\\n- Migrations: `db/migrations/`; verify: `node db/verify-schema.mjs`\\n\\n## Key MVs\\n\\n| View | Use |\\n|------|-----|\\n| mv_smart_money_latest | Smart money signals |\\n| mv_entity_signal_latest | Super investor signals |\\n| mv_one_percent_club_latest | 1% Club |\\n\\nRefresh: `npm run db:refresh-si-views` and `refresh_all_views()` for MF smart-money MVs.\\n"}')

def write_file(rel: str, content: str, *, skip_if_exists: bool = False) -> str:
    path = ROOT / Path(rel)
    if skip_if_exists and path.exists():
        return "skipped"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8", newline="\n")
    return "written"

def main() -> int:
    created: list[str] = []
    skipped: list[str] = []
    errors: list[str] = []
    optional = {"DESIGN.md": True, "CONTEXT.md": True}
    subagent_skip = lambda r: r.startswith(".cursor/subagents/")

    for rel, content in sorted(FILES.items()):
        try:
            status = write_file(
                rel,
                content,
                skip_if_exists=optional.get(rel, False) or subagent_skip(rel),
            )
            (skipped if status == "skipped" else created).append(rel)
        except Exception as exc:
            errors.append(f"{rel}: {exc}")

    print(f"Written: {len(created)}")
    for p in created:
        print(f"  + {p}")
    if skipped:
        print(f"Skipped: {len(skipped)}")
        for p in skipped:
            print(f"  ~ {p}")
    if errors:
        for e in errors:
            print(f"ERROR {e}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
